(function(){'use strict';
const $=id=>document.getElementById(id),outcome=document.querySelector('#craft-content .result-extra>.fold-body'),fold=document.createElement('details');fold.id='craft-actions';fold.className='fold craft-actions';fold.innerHTML='<summary>Действия с этой партией</summary><div class="craft-actions-body"><label>Название расчёта, необязательно<input id="craft-action-name" maxlength="80" placeholder="Название предмета и объём"></label><div class="grid2"><label>Куда добавить<select id="craft-action-destination"><option value="both">Мои крафты и сравнение</option><option value="save">Только мои крафты</option><option value="compare">Только сравнение</option></select></label><button id="craft-action-add" class="button primary" type="button">Добавить расчёт</button></div><p id="craft-action-status" class="hint" role="status"></p><div class="craft-actions-grid"></div></div>';outcome.append(fold);
for(const id of ['craft-training','craft-shipping','record-craft','deal-from-craft'])fold.querySelector('.craft-actions-grid').append($(id));
$('craft-action-add').onclick=()=>{try{const x=CraftApp.snapshot(),destination=$('craft-action-destination').value,name=$('craft-action-name').value.trim()||(x.recipe.name+' · '+x.result.amount+' шт.').slice(0,80);ScenarioUI.quick(destination,name);$('craft-action-status').textContent=destination==='save'?'Сохранено в «Мои крафты».':destination==='compare'?'Добавлено в сравнение без сохранения в «Мои крафты».':'Сохранено в «Мои крафты» и добавлено в сравнение.';}catch(e){$('craft-action-status').textContent=e.message;}};
})();
